1|#!/usr/bin/env bash
2|set -euo pipefail
3|unset GIT_INDEX_FILE
4|
5|usage() {
6|  echo "usage: workspace-recovery.sh save [label] | restore <recovery-ref>" >&2
7|  exit 2
8|}
9|
10|die() {
11|  echo "workspace recovery: $*" >&2
12|  exit 1
13|}
14|
15|command -v git >/dev/null 2>&1 || die "git is unavailable"
16|root=$(git rev-parse --show-toplevel 2>/dev/null) || die "not an ordinary Git workspace"
17|head=$(git -C "$root" rev-parse --verify HEAD 2>/dev/null) || die "unborn HEAD is unsupported"
18|[ -z "$(git -C "$root" ls-files -u)" ] || die "an unmerged index is unsupported"
19|saved_ref=
20|
21|write_recovery_commit() {
22|  local message=$1 tree=$2
23|  shift 2
24|  printf '%s\n' "$message" |
25|    GIT_AUTHOR_NAME="TBH Recovery" \
26|    GIT_AUTHOR_EMAIL="recovery@localhost" \
27|    GIT_COMMITTER_NAME="TBH Recovery" \
28|    GIT_COMMITTER_EMAIL="recovery@localhost" \
29|    git -C "$root" commit-tree "$tree" "$@"
30|}\

