87|collect_one_restore_collision() {
88|  local path=$1 leaf=$2 candidates=$3 directory_candidates=$4
89|  if [ ! -e "$root/$path" ] && [ ! -L "$root/$path" ]; then
90|    return
91|  fi
92|  if [ "$leaf" = false ] && [ -d "$root/$path" ] && [ ! -L "$root/$path" ]; then
93|    return
94|  fi
95|  if [ "$leaf" = true ] && [ -d "$root/$path" ] && [ ! -L "$root/$path" ]; then
96|    printf '%s\0' "$path" >>"$directory_candidates"
97|  fi
98|  printf '%s\0' "$path" >>"$candidates"
