101|refuse_unsafe_restore_collisions() {
102|  local recovery_commit=$1 collision_dir path_list index_paths candidates directory_candidates
103|  local ignore_candidates ignore_matches path ancestor previous_path index_path index_eof
104|  local directory_path directory_eof tracked_exact leaf_directory ignore_status ignored_path
105|  local first_candidate LC_ALL=C
