120|  git -C "$root" ls-files -z >"$index_paths"
121|
122|  previous_path=
123|  while IFS= read -r -d '' path; do
124|    ancestor=$path
125|    while [[ "$ancestor" == */* ]]; do
126|      ancestor=${ancestor%/*}
