136|  LC_ALL=C sort -zu "$candidates" -o "$candidates"
137|  LC_ALL=C sort -zu "$directory_candidates" -o "$directory_candidates"
138|  LC_ALL=C sort -zu "$index_paths" -o "$index_paths"
