161|      tracked_exact=true
162|    fi
163|
164|    while [ "$directory_eof" = false ] && [[ "$directory_path" < "$path" ]]; do
165|      if ! IFS= read -r -d '' directory_path <&8; then
166|        directory_eof=true
167|        directory_path=
168|      fi
169|    done
