171|    if [ "$directory_eof" = false ] && [ "$directory_path" = "$path" ]; then
172|      leaf_directory=true
173|    fi
174|
175|    [ "$tracked_exact" = true ] && continue
176|    [ "$leaf_directory" = false ] || die "restore would replace an untracked directory: $path"
