178|  done <"$candidates"
179|  exec 9<&-
180|  exec 8<&-
181|
182|  if [ -s "$ignore_candidates" ]; then
183|    if git -C "$root" check-ignore -z --stdin --no-index \
184|      <"$ignore_candidates" >"$ignore_matches"; then
